"""Reading times that people write."""

import re

_PART = re.compile(r"(\d+)([hms])")
_SCALE = {"h": 3600, "m": 60, "s": 1}


def parse_clock(text: str) -> int:
    """Minutes after midnight for a time like "09:30"."""
    hours, minutes = text.split(":")
    return int(hours) * 60 + int(minutes)


def parse_duration(text: str) -> int:
    """Seconds in a duration like "1h30m"."""
    return sum(int(number) * _SCALE[unit] for number, unit in _PART.findall(text))

import unittest

from timeparse import parse_clock, parse_duration


class ClockTest(unittest.TestCase):
    def test_clock(self) -> None:
        self.assertEqual(parse_clock("09:30"), 570)


class DurationTest(unittest.TestCase):
    def test_hours_and_minutes(self) -> None:
        self.assertEqual(parse_duration("1h30m"), 5400)

    def test_one_unit(self) -> None:
        self.assertEqual(parse_duration("45s"), 45)
        self.assertEqual(parse_duration("2h"), 7200)


if __name__ == "__main__":
    unittest.main()
